25: /**
26: * Invokes a unary function accepting a single-precision complex floating-point number and returning a single-precision floating-point number.
27: *
28: * ## Notes
29: *
30: * -   This function expects that the callback `info` argument provides access to the following JavaScript arguments:
31: *
32: *     -   `x`: input value.
33: *
34: * @param env    environment under which the function is invoked
35: * @param info   callback data
36: * @param fcn    unary function
37: * @return       function return value as a Node-API complex-like object
38: */
39: napi_value stdlib_math_base_napi_c_f( napi_env env, napi_callback_info info, float (*fcn)( stdlib_complex64_t ) ) {
40: 	napi_status status;
41: 
42: 	size_t argc = 1;
43: 	napi_value argv[ 1 ];
44: 	status = napi_get_cb_info( env, info, &argc, argv, NULL, NULL );
45: 	assert( status == napi_ok );
46: 
47: 	if ( argc < 1 ) {
48: 		status = napi_throw_error( env, NULL, "invalid invocation. Must provide a complex number." );
49: 		assert( status == napi_ok );
50: 		return NULL;
51: 	}
52: 
53: 	bool hprop;
54: 	status = napi_has_named_property( env, argv[ 0 ], "re", &hprop );
55: 	assert( status == napi_ok );
56: 	if ( !hprop ) {
57: 		status = napi_throw_type_error( env, NULL, "invalid argument. Argument must have a real component." );
58: 		assert( status == napi_ok );
59: 		return NULL;
60: 	}
61: 
62: 	napi_value xre;
63: 	status = napi_get_named_property( env, argv[ 0 ], "re", &xre );
64: 	assert( status == napi_ok );
65: 
66: 	napi_valuetype xretype;
67: 	status = napi_typeof( env, xre, &xretype );
68: 	assert( status == napi_ok );
69: 	if ( xretype != napi_number ) {
